import 'dart:convert';

import 'package:crypto/crypto.dart';

/// An immutable, revision-pinned package. URLs and checksums are app-supplied,
/// never generated by the language model or accepted from a chat message.
class ModelManifest {
  ModelManifest({
    required this.id,
    required this.label,
    required this.source,
    required this.revision,
    required this.format,
    required this.quantization,
    required this.license,
    required this.runtime,
    required this.runtimeRevision,
    required List<ModelFile> files,
  }) : files = List.unmodifiable(files) {
    if (!RegExp(r'^[a-z0-9-]+$').hasMatch(id) ||
        !RegExp(r'^[a-f0-9]{40}$').hasMatch(revision) ||
        !RegExp(r'^[a-f0-9]{40}$').hasMatch(runtimeRevision) ||
        files.isEmpty ||
        files.map((f) => f.name).toSet().length != files.length) {
      throw const FormatException('Некорректный манифест модели');
    }
    for (final f in files) {
      if (f.url.scheme != 'https' ||
          f.url.host != 'huggingface.co' ||
          !f.url.path.startsWith('/$source/resolve/$revision/')) {
        throw const FormatException('Источник модели не закреплён за ревизией');
      }
    }
  }

  factory ModelManifest.fromJson(Map<String, dynamic> json) => ModelManifest(
    id: json['id'] as String,
    label: json['label'] as String,
    source: json['source'] as String,
    revision: json['revision'] as String,
    format: json['format'] as String,
    quantization: json['quantization'] as String,
    license: json['license'] as String,
    runtime: json['runtime'] as String,
    runtimeRevision: json['runtimeRevision'] as String,
    files: (json['files'] as List)
        .map((f) => ModelFile.fromJson(Map<String, dynamic>.from(f as Map)))
        .toList(),
  );

  final String id, label, source, revision, format, quantization;
  final String license, runtime, runtimeRevision;
  final List<ModelFile> files;

  int get downloadBytes => files.fold(0, (sum, file) => sum + file.size);

  /// Incorporates every file hash: a manifest update cannot resume a different
  /// package even if its source revision was accidentally left unchanged.
  String get packageKey =>
      '$id-$revision-${sha256.convert(utf8.encode(jsonEncode(toJson()))).toString().substring(0, 16)}';

  Map<String, dynamic> toJson() => {
    'id': id,
    'label': label,
    'source': source,
    'revision': revision,
    'format': format,
    'quantization': quantization,
    'license': license,
    'runtime': runtime,
    'runtimeRevision': runtimeRevision,
    'files': files.map((f) => f.toJson()).toList(),
  };
}

class ModelFile {
  ModelFile({
    required this.name,
    required this.size,
    required this.checksum,
    required this.url,
  }) {
    // Flat app-controlled packages: no path traversal or alternate configs.
    if (!RegExp(r'^[a-zA-Z0-9_.-]+$').hasMatch(name) ||
        name == '.' ||
        name == '..' ||
        size <= 0 ||
        !RegExp(r'^[a-f0-9]{64}$').hasMatch(checksum)) {
      throw const FormatException('Некорректное описание файла модели');
    }
  }

  factory ModelFile.fromJson(Map<String, dynamic> json) => ModelFile(
    name: json['name'] as String,
    size: json['size'] as int,
    checksum: json['sha256'] as String,
    url: Uri.parse(json['url'] as String),
  );

  final String name, checksum;
  final int size;
  final Uri url;

  Map<String, dynamic> toJson() => {
    'name': name,
    'size': size,
    'sha256': checksum,
    'url': url.toString(),
  };
}
